{"code":"def generate(rng):
 g=[[0]*17 for _ in range(17)]
 for k in (5,11):
  for x in range(17): g[k][x]=7; g[x][k]=7
 # reference random connected small shape in first panel
 pts=[(i,j) for i in range(1,4) for j in range(1,4) if rng.random()<.45]
 if not pts: pts=[(2,2)]
 for i,j in pts:g[i][j]=9
 # random objects in other panels
 for a in range(3):
  for b in range(3):
   if a==0 and b==0: continue
   for i,j in [(i,j) for i in range(1,4) for j in range(1,4) if rng.random()<.2]:
    g[6*a+i][6*b+j]=9
 return g"}

